17	import type { IUniverInstanceService, Workbook } from '@univerjs/core';
18	import type { IDefinedNamesService, IFunctionService, ISuperTableService } from '@univerjs/engine-formula';
19	import { Tools, UniverInstanceType } from '@univerjs/core';
20	import { isReferenceStringWithEffectiveColumn } from '@univerjs/engine-formula';
21	import { hasCJKText } from '@univerjs/engine-render';
22	
23	interface IValidateDefinedNameOptions {
24	    unitId: string;
25	    formulaOrRefString: string;
26	    univerInstanceService: IUniverInstanceService;
27	    definedNamesService: IDefinedNamesService;
28	    superTableService: ISuperTableService;
29	    functionService: IFunctionService;
30	    id?: string;
31	}
32	
33	export function validateDefinedName(name: string, options: IValidateDefinedNameOptions): true | string {
34	    if (name.length === 0) {
35	        return 'definedName.nameEmpty';
36	    }
37	
38	    const { unitId, formulaOrRefString, univerInstanceService, definedNamesService, superTableService, functionService, id } = options;
39	
40	    /**
41	     * The defined name can't be duplicate with existing defined names.
42	     * If id is provided, it means we are updating an existing defined name. We should allow the name to be the same as itself.
43	     */
44	    const existingDefinedName = definedNamesService.getValueByName(unitId, name);
45	    if (
46	        existingDefinedName &&
47	        (id === null || id === undefined || id.length === 0 || existingDefinedName.id !== id)
48	    ) {
49	        return 'definedName.nameDuplicate';
50	    }
51	
52	    // The defined name can't be duplicate with existing table names.
53	    if (superTableService.hasTable(unitId, name)) {
54	        return 'definedName.nameDuplicate';
55	    }
56	
57	    // The defined name can't be a reference string with effective column, which will cause confusion.
58	    if (
59	        !Tools.isValidParameter(name) ||
60	        isReferenceStringWithEffectiveColumn(name) ||
61	        (!Tools.isStartValidPosition(name) && !hasCJKText(name.substring(0, 1)))
62	    ) {
63	        return 'definedName.nameInvalid';
64	    }
65	
66	    const workbook = univerInstanceService.getUnit<Workbook>(unitId, UniverInstanceType.UNIVER_SHEET);
67	    if (!workbook) {
68	        throw new Error(`Workbook not found for unitId: ${unitId}`);
69	    }
70	
71	    const worksheets = workbook.getSheets();
72	
73	    // The defined name can't be duplicate with existing sheet names.
74	    if (worksheets.some((sheet) => sheet.getName() === name)) {
75	        return 'definedName.nameSheetConflict';
76	    }
77	
78	    if (formulaOrRefString.length === 0) {
79	        return 'definedName.formulaOrRefStringEmpty';
80	    }
81	
82	    // The defined name can't be duplicate with existing function names.
83	    if (functionService.hasExecutor(name.toUpperCase())) {
84	        return 'definedName.nameConflict';
85	    }
86	
87	    return true;
88	}
